import{c as r,Z as t,Q as l,j as s,m as n,o}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"望庐山瀑布","description":"","frontmatter":{"title":"望庐山瀑布","author":"李白","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/7.md","filePath":"books/shici/tangshi/7.md"}'),h={name:"books/shici/tangshi/7.md"};function u(c,a,p,d,q,_){const e=t("PoemAuthor"),i=t("PoemNav");return l(),s("div",null,[a[0]||(a[0]=n('<h1 id="望庐山瀑布" tabindex="-1">望庐山瀑布 <a class="header-anchor" href="#望庐山瀑布" aria-label="Permalink to &quot;望庐山瀑布&quot;">​</a></h1><p><strong>[唐] <a href="/authors/libai.html">李白</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>日照香炉生紫烟，遥看瀑布挂前川。 飞流直下三千尺，疑是银河落九天。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>庐山：在今江西省九江市南，是我国著名的风景区</li><li>香炉：即香炉峰，在庐山西北，因形似香炉且山上云雾缭绕而得名</li><li>紫烟：指日光照射下的云雾呈现出紫色的烟雾状</li><li>遥看：远远望去</li><li>挂前川：挂在前面的河流之上，形容瀑布如白练悬挂</li><li>飞流：飞腾直下的水流</li><li>九天：天的最高处，古人认为天有九重</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>阳光照耀着香炉峰，升腾起紫色的烟雾。远远望去，瀑布像一条白练悬挂在山前的河流之上。飞腾的水流从三千尺的高处直泻而下，让人怀疑是银河从九天之上落到了人间。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是李白游历庐山时所作，描绘了庐山瀑布雄奇壮丽的景色，是描写瀑布的千古绝唱。</p><p>首句&quot;日照香炉生紫烟&quot;，从远处落笔，写香炉峰在日光照射下的奇景。&quot;紫烟&quot;二字，既写出了云雾在阳光下的色彩变化，又增添了一种神秘缥缈的意境，为瀑布的出现做了铺垫。</p><p>次句&quot;遥看瀑布挂前川&quot;，点出题目中的&quot;望&quot;字，写远远望去瀑布的景象。&quot;挂&quot;字用得极妙，将动态的瀑布化为静态的画面，如一幅巨大的白练悬挂山间，给人以强烈的视觉冲击。</p><p>后两句&quot;飞流直下三千尺，疑是银河落九天&quot;，是全诗的精华所在。诗人运用夸张和想象的手法，将瀑布的气势推向极致。&quot;三千尺&quot;极言其高，&quot;银河落九天&quot;更是将瀑布的壮观与神话传说相结合，创造出一种超凡脱俗的意境。这种大胆的想象和夸张，正是李白诗歌浪漫主义风格的典型体现。</p><p>全诗语言明快，意境雄奇，将庐山瀑布的壮美描绘得淋漓尽致，读来令人神往。</p>',14)),o(e,{name:"李白",years:"701年－762年",desc:"字太白，号青莲居士，又号“谪仙人”，唐代伟大的浪漫主义诗人，被后人誉为“诗仙”。其诗风雄奇豪放，想象丰富，意境奇妙，语言流转自然。",link:"/authors/libai"}),o(i)])}const f=r(h,[["render",u]]);export{b as __pageData,f as default};
